programs.haiku:
"""Layer 15 MLP down-proj component 2117 (Qwen3-1.7B), as a readable rule.

What it is: a rank-one slice of the MLP's output. Its activation is almost entirely
a read-out of one MLP hidden unit (neuron 2117 of layer 15), which correlates r = 0.62 with it
(about 40% of its variance). That unit is a diffuse, context-dependent feature, so this program
only captures the surface part of it, from the current token and the token before it:

- Linking words and copulas ("and", "or", "but", "so", "which", "where", "is", "was",
  "has", "then", "because"...) push the activation up.
- Clause punctuation (",", ")", "(", "),") pushes it up strongly.
- A closing mark just before the token ("`", "$", a closing quote, bracket) pushes it up.
- Digits and capitalised words push it down; other symbols (code, paths) push it up a little.
- The first token of each document is 0 (the component is silent there).

It explains only a few percent of the variance: the component is not well described by
the surface words of the text. The rest of the activation depends on the wider context.

Main program: `step` below. It is stateless apart from reading the newest tokens.
"""

import re

LINKING_WORDS = {
    "and", "or", "but", "so", "which", "where", "that", "is", "was", "are", "were",
    "has", "have", "be", "then", "since", "because", "if",
}
CLAUSE_PUNCTUATION = {",", ")", "(", "),", ")."}
CLOSING_MARKS = {
    '"', "'", "’", "”", "`", "$", "$$", "}$", ")$", "」", "》", "）", "°", '",', "`,", "$,",
}
BASE = 0.2
READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip()
    value = BASE
    if tok.lower() in LINKING_WORDS:
        value += 0.85
    if tok in CLAUSE_PUNCTUATION:
        value += 1.0
    if re.fullmatch(r"\d+", tok):
        value -= 0.2
    if re.fullmatch(r"[A-Z][a-z]+", tok):
        value -= 0.2
    if re.fullmatch(r"[^\w\s]+", tok) and tok not in CLAUSE_PUNCTUATION | {".", ":"}:
        value += 0.13
    if prev in CLOSING_MARKS:
        value += 0.7
    return carry, float(value)

"""Elaboration cues in running text.

The component dips negative on the words that open an example, a specification or a
restatement: "for example", "e.g.", "i.e.", "such as", "in particular", "namely", "that
is", "in other words", and sentence-initial set-ups such as "In", "For", "Here", "This".
It rises a little on sentence-initial contrast words ("However", "Although", "But").
Everything else is near zero. The values are scaled down from the group means, which
gives the best fit for this sparse signal.
"""
READS = ()

# words that name an example or a specification
EXAMPLE_WORDS = {"e.g", ".g", "i.e", ".e", "ie", "namely", "specifically", "especially",
                 "particularly", "instance", "example", "examples", "including", "例如", "比如",
                 "например", "ejemplo", "exemplo"}
# sentence-initial words that open a restatement or an elaboration
SETUP_WORDS = {"in", "for", "here", "this", "that", "these", "such", "see", "note", "why",
               "more", "indeed", "like", "by", "to", "at", "as"}
# sentence-initial words that turn to a contrast or a concession
CONTRAST_WORDS = {"however", "but", "although", "though", "while", "despite", "nevertheless",
                  "yet", "unfortunately", "alternatively", "well", "still"}
SENTENCE_END = {".", "?", "!", "\n", "\n\n", ""}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    starts_sentence = prev in SENTENCE_END or prefix.token_strings[-2:-1] == ["\n"]
    if cur in EXAMPLE_WORDS:
        return carry, -2.2
    if cur == "particular" and prev == "in":
        return carry, -2.5
    if cur == "is" and prev == "that":
        return carry, -1.4
    if cur == "words" and prev == "other":
        return carry, -2.5
    if cur == "as" and prev == "such":
        return carry, -1.2
    if cur == "see" and prev == "(":
        return carry, -1.5
    if cur in ("such", "like"):
        return carry, -0.7
    if starts_sentence and cur in SETUP_WORDS:
        return carry, -0.9
    if starts_sentence and cur in CONTRAST_WORDS:
        return carry, 0.3
    return carry, 0.0

"""Predicts layers.15.mlp.down_proj:2135, a component that fires when the next token is
likely to open a quoted string in code.

It reads only the current token (and the token before it). It is large on the token just
before a string literal:
  - the colon after a JSON key whose value is text ("name": , "command": , "path": ...),
    strongest for text keys, weaker for other keys;
  - a print or output call that takes a string: print, printf, println, echo, cout <<,
    console.log(, .Printf(, querySelector(, #include, href=;
  - a module or test call that takes a string: require, describe, Go's fmt;
  - an f-string opener (f" and mild values on the punctuation that leads into a
    string or list item (", and :).
Everywhere else (ordinary prose, most code) it predicts 0.
"""

READS = ()

# JSON keys whose values are usually text
TEXT_KEYS = {"name", "command", "path", "message", "description", "url", "text", "title", "email"}
# print or output words, and the method names that print or log a string
PRINT_WORDS = {"print", "printf", "println", "Printf", "Println", "echo", "cout", "scanf", "puts", "<<", "#include", "href"}
PRINT_METHODS = {"log", "println", "Printf", "Println", "print", "Append", "querySelector", "out", "split"}
# module loaders and test blocks that take a string argument
LOADERS = {"require", "describe", "fmt"}
# punctuation that leads into a value, a string or a list item
PUNCT = {'",', ":", ":\n", ":\n\n", " :"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = carry or ""  # the token before this one, within the same document
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    word = tok.strip().lstrip(".")
    if tok.endswith('":'):
        value = 21.0 if prev.strip() in TEXT_KEYS else 9.0
    elif word in TEXT_KEYS and prev.endswith('"'):
        value = 6.0
    elif tok.startswith(".") and word in PRINT_METHODS:
        value = 10.0
    elif word in PRINT_WORDS:
        value = 10.0
    elif word in LOADERS:
        value = 6.0
    elif word == "(f":
        value = 8.0
    elif tok in PUNCT or tok.endswith(":\n"):
        value = 3.6
    else:
        value = 0.0
    return tok, value

"""Layer 15 MLP hidden unit 2140 (the component's activation is this unit times a fixed
scale), predicted from the text just before it.

The unit is noisy and mostly context-driven. What lexical facts it does track:
  * a number that starts right after an opening bracket, e.g. "(-3" or "[12", is
    pushed clearly negative;
  * a digit right after a minus sign leans positive;
  * other digits lean slightly positive, and a comma leans slightly positive.
Everything else is predicted as 0. The values are group means measured on training text.
"""

READS = ()

OPEN = {"(", "[", "{"}
MINUS = {"-", "−"}
DIGITS = set("0123456789")


def _same_doc_prev(prefix):
    """The previous token's text, or '' at a document start."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2].strip()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = _same_doc_prev(prefix)
    if cur in DIGITS:
        if prev in OPEN:
            return carry, -0.6
        if prev in MINUS:
            return carry, 0.25
        return carry, 0.07
    if cur in OPEN:
        return carry, -0.15
    if prev == ",":
        return carry, 0.1
    return carry, 0.0

"""Layer 15 MLP down_proj, component 2170: a diffuse signal that tokens explain only a little.

Its activation is the MLP hidden unit 2170 read through one direction, so it depends mostly on
context: the current token's identity explains only a few percent of its variance, and most of
the rest is spread over many small contributions. The part a word list can capture is this: it
is positive on words about variation, options and defaults ("vary", "varied", "optional",
"default", "depend", "differ", "±") and slightly negative on some prepositions ("by", "from",
"per", "between", "after", "in"). This program predicts those values from the current token
alone, and 0 everywhere else. It explains well under 1% of the activation's variance.
"""

READS = ()

STRONG = {"vary", "varies", "varied", "defaults", "optional", "±", "+/-", "dynamically"}
MODERATE = {
    "differ", "differed", "depend", "depends", "depending", "dependent", "default",
    "variation", "variations", "differences", "altered", "ambiguous", "uniquely",
    "invariant", "randomly", "parameter",
}
PREPOSITIONS = {"by", "from", "per", "between", "after", "in"}


def step(carry, prefix, upstream):
    """The activation at this position, from the newest token alone."""
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        value = 0.7
    elif word in MODERATE:
        value = 0.4
    elif word in PREPOSITIONS:
        value = -0.15
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 2172: a weak, diffuse read of the MLP hidden layer.

What it reads: this component's input direction is almost entirely hidden unit 2172 of
layer 15's MLP (weight 0.63 on that unit; the rest is spread thinly over ~6,000 others).
Its activation is that unit's value times a fixed scale, plus a small sum of many other
units. The activation is about -0.03 on average with spread 0.30, and it is not a
recognisable token feature: no token identity, word class, or position explains more
than about 1-2% of its variance.

What this program does: predicts the activation from the class of the token being
predicted, using the mean activation measured per class on training text:
  - first token of a document: about 0 (the component is silent there);
  - Han (Chinese/Japanese) characters: clearly negative (about -0.11);
  - newlines: slightly positive (about +0.04);
  - ordinary words, digits and spaces: about -0.01 to -0.035;
  - punctuation: about 0.
This explains roughly 0.1% of the variance on held-out text: the component is
essentially unexplained by surface features.
"""

READS = ()

START = 0.0
HAN = -0.11
NEWLINE = 0.04
PUNCT = 0.0
DIGIT_OR_SPACE = -0.01
WORD = -0.035


def is_han(ch):
    return "一" <= ch <= "鿿" or "㐀" <= ch <= "䶿"


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, START
    stripped = text.strip()
    if any(is_han(ch) for ch in text):
        value = HAN
    elif "\n" in text:
        value = NEWLINE
    elif not stripped or stripped.isdigit():
        value = DIGIT_OR_SPACE
    elif not any(ch.isalnum() for ch in stripped):
        value = PUNCT
    else:
        value = WORD
    return carry, float(value)
